body.tl-refresh:not(#tl) .elementor-widget-heading:has(:is([data-tl-role="title"], [data-tl-role="display"])) > .elementor-widget-container {
    margin-bottom: 0.35rem !important;
}
body.tl-refresh:not(#tl) .elementor-widget-heading:has([data-tl-role]) + .elementor-widget-text-editor > .elementor-widget-container {
    margin-top: 0.75rem !important;
}

/* ------------------------------------------------------------------ *
 * 3. Links, rules, images.
 * ------------------------------------------------------------------ */
body.tl-refresh:not(#tl) :is(main, .site-content) a,
body.tl-refresh:not(#tl) :is(main, .site-content) a:visited {
    color: inherit !important;
